       !Array.isArray(d.dice)||d.dice.length!==5||!d.dice.every(n=>Number.isInteger(n)&&n>=1&&n<=6)||
       !Array.isArray(d.held)||d.held.length!==5||!d.held.every(v=>typeof v==='boolean')||
