_0,60px);width:100%;flex-wrap:wrap;}.yatzy-scene .yatzy-dice{display:flex;justify-content:center;gap:var(--size-space-7_0,8px);padding:var(--size-space-6_0,4px) 0;flex:none;}.yatzy-scene .yatzy-dice .shared-die{width:var(--size-length-38_0,36px);}.yatzy-scene .yatzy-roll{min-height:var(--size-length-40_0,40px);max-width:100%;margin:0;}.yatzy-scene .yatzy-controls>.yatzy-roll{flex:1 0 100%;max-width:var(--size-length-240_0,240px);}
